-- Austria milestone translations (ES/DE/FR) — replaces the
-- English-placeholder draft stub generated by new_country_scaffold.py.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2g-2014', 'es', 'Entra en vigor el mandato federal de facturación electrónica B2G', 'La República de Austria deja de aceptar facturas en papel de los proveedores de organismos del gobierno federal (IKTKonG §5, BGBl. I Nr. 35/2012). Las facturas deben presentarse electrónicamente, ya sea en formato XML ebInterface o como UBL a través de Peppol — uno de los mandatos B2G más tempranos de la UE.', '["Regístrese como proveedor del gobierno a través del portal USP (erechnung.gv.at)", "Confirme que su software de facturación admite ebInterface o Peppol BIS 3.0"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2g-2014', 'de', 'Die föderale B2G-E-Rechnungspflicht tritt in Kraft', 'Die Republik Österreich akzeptiert keine Papierrechnungen mehr von Lieferanten an Bundesbehörden (IKTKonG §5, BGBl. I Nr. 35/2012). Rechnungen müssen elektronisch übermittelt werden, entweder im ebInterface-XML-Format oder als UBL über Peppol — eine der frühesten B2G-Pflichten in der EU.', '["Registrieren Sie sich als Regierungslieferant über das USP-Portal (erechnung.gv.at)", "Bestätigen Sie, dass Ihre Rechnungssoftware ebInterface oder Peppol BIS 3.0 unterstützt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2g-2014', 'fr', 'L''obligation fédérale de facturation électronique B2G entre en vigueur', 'La République d''Autriche cesse d''accepter les factures papier des fournisseurs des organismes du gouvernement fédéral (IKTKonG §5, BGBl. I Nr. 35/2012). Les factures doivent être soumises électroniquement, soit au format XML ebInterface, soit en UBL via Peppol — l''une des obligations B2G les plus précoces de l''UE.', '["Inscrivez-vous en tant que fournisseur du gouvernement via le portail USP (erechnung.gv.at)", "Confirmez que votre logiciel de facturation prend en charge ebInterface ou Peppol BIS 3.0"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2g-extended-2018', 'es', 'El mandato B2G se amplía a todas las entidades adjudicadoras centrales', 'La Ley Federal de Contratación Pública de 2018 (BVergG 2018, §368) amplía la obligación existente de facturación electrónica más allá de los ministerios federales centrales para abarcar todas las entidades adjudicadoras centrales. Varios de los nueve Länder (estados) de Austria — incluidos Viena, Baja Austria y Alta Austria — han adoptado desde entonces requisitos comparables propios.', '["Compruebe si su entidad adjudicadora concreta (federal, estatal o municipal) tiene su propio requisito de facturación electrónica", "Confirme que la cobertura de ebInterface o Peppol se extiende a todos los organismos públicos a los que factura"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2g-extended-2018', 'de', 'Die B2G-Pflicht wird auf alle zentralen öffentlichen Auftraggeber ausgeweitet', 'Das Bundesvergabegesetz 2018 (BVergG 2018, §368) erweitert die bestehende E-Rechnungspflicht über die zentralen Bundesministerien hinaus auf alle zentralen öffentlichen Auftraggeber. Mehrere der neun österreichischen Länder — darunter Wien, Niederösterreich und Oberösterreich — haben inzwischen eigene vergleichbare Anforderungen eingeführt.', '["Prüfen Sie, ob Ihr konkreter Auftraggeber (Bund, Land oder Gemeinde) eine eigene E-Rechnungspflicht hat", "Bestätigen Sie, dass die ebInterface- oder Peppol-Abdeckung den gesamten Kreis öffentlicher Stellen umfasst, an die Sie fakturieren"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2g-extended-2018', 'fr', 'L''obligation B2G s''étend à tous les pouvoirs adjudicateurs centraux', 'La loi fédérale sur les marchés publics de 2018 (BVergG 2018, §368) élargit l''obligation de facturation électronique existante au-delà des ministères fédéraux centraux pour couvrir tous les pouvoirs adjudicateurs centraux. Plusieurs des neuf Länder (États) autrichiens — dont Vienne, la Basse-Autriche et la Haute-Autriche — ont depuis adopté leurs propres exigences comparables.', '["Vérifiez si votre pouvoir adjudicateur spécifique (fédéral, régional ou municipal) a sa propre exigence de facturation électronique", "Confirmez que la couverture ebInterface ou Peppol s''étend à l''ensemble des organismes publics auxquels vous facturez"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-ebinterface-70', 'es', 'Se espera ebInterface 7.0, con vinculación formal de sintaxis a EN 16931', 'AUSTRIAPRO (el grupo de trabajo de facturación electrónica de la WKO) está preparando ebInterface 7.0 para su lanzamiento en el cuarto trimestre de 2026, añadiendo una vinculación formal de sintaxis con la norma europea de facturación electrónica EN 16931. No se ha anunciado ninguna migración obligatoria desde 6.0/6.1, y el desarrollo avanza teniendo en cuenta la compatibilidad con versiones anteriores.', '["No se requiere ninguna acción todavía — las implementaciones existentes de ebInterface 6.0/6.1 siguen siendo válidas", "Esté atento al lanzamiento de la versión 7.0 y a cualquier orientación futura sobre el momento de adopción"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-ebinterface-70', 'de', 'ebInterface 7.0 erwartet, mit formaler Syntaxbindung an EN 16931', 'AUSTRIAPRO (der E-Billing-Arbeitskreis der WKO) bereitet ebInterface 7.0 für die Veröffentlichung im vierten Quartal 2026 vor und fügt eine formale Syntaxbindung an die europäische E-Rechnungs-Norm EN 16931 hinzu. Ein verpflichtender Umstieg von 6.0/6.1 wurde nicht angekündigt, die Entwicklung erfolgt unter Berücksichtigung der Abwärtskompatibilität.', '["Derzeit ist keine Maßnahme erforderlich — bestehende ebInterface-6.0/6.1-Implementierungen bleiben gültig", "Achten Sie auf die Veröffentlichung von 7.0 und künftige Hinweise zum Umstellungszeitpunkt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-ebinterface-70', 'fr', 'ebInterface 7.0 attendu, avec liaison syntaxique formelle à l''EN 16931', 'AUSTRIAPRO (le groupe de travail e-facturation de la WKO) prépare ebInterface 7.0 pour une publication au quatrième trimestre 2026, ajoutant une liaison syntaxique formelle à la norme européenne de facturation électronique EN 16931. Aucune migration obligatoire depuis la 6.0/6.1 n''a été annoncée, et le développement se poursuit dans un souci de rétrocompatibilité.', '["Aucune action n''est requise pour l''instant — les implémentations existantes d''ebInterface 6.0/6.1 restent valides", "Surveillez la publication de la version 7.0 et toute orientation future sur le calendrier d''adoption"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2b-proposal-2026', 'es', 'Se espera una propuesta formal de facturación electrónica B2B nacional', 'Austria no tiene hoy ningún mandato nacional de facturación electrónica B2B ni de reporte en tiempo real — la facturación estructurada B2B sigue siendo voluntaria, aunque ampliamente adoptada, especialmente entre empresas con socios comerciales de la UE ya sujetos a regímenes obligatorios. El Ministerio de Hacienda (BMF) ha señalado que adoptará un enfoque basado en Peppol, siguiendo el ejemplo de Bélgica y los Países Bajos, con una propuesta formal esperada para el tercer trimestre de 2026 — aún no publicada a principios de agosto de 2026.', '["Siga al BMF y al RIS (Rechtsinformationssystem) para conocer la propuesta formal una vez publicada", "Si ya cuenta con capacidad Peppol para B2G, no debería necesitar infraestructura adicional para un eventual mandato B2B"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2b-proposal-2026', 'de', 'Formeller Vorschlag für inländische B2B-E-Rechnung erwartet', 'Österreich hat heute keine inländische B2B-E-Rechnungs- oder Echtzeitmeldepflicht — strukturierte B2B-Rechnungsstellung bleibt freiwillig, wenn auch weit verbreitet, insbesondere bei Unternehmen mit EU-Handelspartnern, die bereits verpflichtenden Regelungen unterliegen. Das Finanzministerium (BMF) hat signalisiert, einen Peppol-basierten Ansatz zu verfolgen, analog zu Belgien und den Niederlanden, wobei ein formeller Vorschlag für das dritte Quartal 2026 erwartet wird — Anfang August 2026 noch nicht veröffentlicht.', '["Verfolgen Sie BMF und RIS (Rechtsinformationssystem) auf den formellen Vorschlag, sobald er veröffentlicht wird", "Bei bestehender Peppol-Fähigkeit für B2G sollte keine zusätzliche Infrastruktur für eine künftige B2B-Pflicht nötig sein"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2b-proposal-2026', 'fr', 'Une proposition formelle de facturation électronique B2B nationale est attendue', 'L''Autriche n''a aujourd''hui aucune obligation nationale de facturation électronique B2B ni de déclaration en temps réel — la facturation structurée B2B reste volontaire, bien que largement adoptée, notamment parmi les entreprises ayant des partenaires commerciaux européens déjà soumis à des régimes obligatoires. Le ministère des Finances (BMF) a signalé qu''il adopterait une approche basée sur Peppol, à l''instar de la Belgique et des Pays-Bas, une proposition formelle étant attendue au troisième trimestre 2026 — non encore publiée début août 2026.', '["Suivez le BMF et le RIS (Rechtsinformationssystem) pour la proposition formelle une fois publiée", "Si vous disposez déjà de la capacité Peppol pour le B2G, aucune infrastructure supplémentaire ne devrait être nécessaire pour une future obligation B2B"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-vida-2030', 'es', 'Entra en vigor el reporte digital B2B transfronterizo de ViDA', 'Independientemente del resultado de cualquier propuesta nacional B2B, la directiva del IVA en la Era Digital (ViDA) de la UE exige capacidad de facturación electrónica estructurada y reporte digital para las transacciones B2B transfronterizas a partir del 1 de julio de 2030 — derecho de la UE confirmado (Directiva (UE) 2025/516 del Consejo, DOUE de 25 de marzo de 2025).', '["Toda empresa que comercie de forma transfronteriza dentro de la UE debería prepararse para tener capacidad de facturación electrónica conforme a EN 16931 para esta fecha, independientemente del calendario nacional de Austria"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-vida-2030', 'de', 'Die grenzüberschreitende B2B-Digitalmeldung nach ViDA tritt in Kraft', 'Unabhängig vom Ausgang eines etwaigen inländischen B2B-Vorschlags verlangt die EU-Richtlinie VAT in the Digital Age (ViDA) ab dem 1. Juli 2030 strukturierte E-Rechnungs- und digitale Meldefähigkeit für grenzüberschreitende B2B-Umsätze — bestätigtes EU-Recht (Richtlinie (EU) 2025/516 des Rates, ABl. vom 25. März 2025).', '["Jedes Unternehmen mit grenzüberschreitendem Handel innerhalb der EU sollte bis zu diesem Datum EN-16931-konforme E-Rechnungsfähigkeit einplanen, unabhängig vom österreichischen Inlandszeitplan"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-vida-2030', 'fr', 'La déclaration numérique B2B transfrontalière ViDA entre en vigueur', 'Quelle que soit l''issue d''une éventuelle proposition nationale B2B, la directive européenne TVA à l''ère numérique (ViDA) exige une capacité de facturation électronique structurée et de déclaration numérique pour les transactions B2B transfrontalières à partir du 1er juillet 2030 — droit de l''UE confirmé (directive (UE) 2025/516 du Conseil, JOUE du 25 mars 2025).', '["Toute entreprise réalisant du commerce transfrontalier au sein de l''UE devrait se préparer à disposer d''une capacité de facturation électronique conforme à l''EN 16931 d''ici cette date, indépendamment du calendrier national autrichien"]');
